// ==================================================
// W2 — GET CONTEXT
// ==================================================

// 1. Get IDs received from W1
const webhook = $('Webhook').first().json;

const conversationId = webhook.body.conversation_id;
const messageId = webhook.body.message_id;
const customerId = webhook.body.customer_id;

if (!conversationId || !messageId || !customerId) {
  throw new Error(
    `Missing IDs. conversation_id=${conversationId}, message_id=${messageId}, customer_id=${customerId}`
  );
}

// ==================================================
// 2. SUPABASE CONNECTION
// ==================================================

const supabaseUrl = 'https://jikdykibhyewrfnlpptv.supabase.co';
const supabaseKey = 'sb_secret_1g3-NRYivFEIBV415V3tnw_GcnjqMkI';

const headers = {
  apikey: supabaseKey,
  Authorization: `Bearer ${supabaseKey}`,
  'Content-Type': 'application/json'
};

async function supabaseGet(table, query) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: `${supabaseUrl}/rest/v1/${table}?${query}`,
    headers
  });
}

// ==================================================
// 3. GET CONVERSATION
// ==================================================

const conversation = await supabaseGet(
  'conversations',
  `select=id,customer_id,channel,status,queue,language,intent,sentiment,urgency_score,order_number,created_at,updated_at&id=eq.${conversationId}`
);

const currentConversation = conversation[0] || null;

if (!currentConversation) {
  throw new Error(
    `Conversation not found: ${conversationId}`
  );
}

// ==================================================
// 4. CONVERT URGENCY SCORE → LEVEL
// ==================================================

const urgencyScore = currentConversation.urgency_score ?? 0;

let urgencyLevel;

if (urgencyScore <= 25) {
  urgencyLevel = 'Low';
} else if (urgencyScore <= 50) {
  urgencyLevel = 'Medium';
} else if (urgencyScore <= 75) {
  urgencyLevel = 'High';
} else {
  urgencyLevel = 'Critical';
}

// ==================================================
// 5. GET CURRENT MESSAGE
// ==================================================

const messages = await supabaseGet(
  'messages',
  `select=id,conversation_id,sender_type,sender_id,content,created_at&id=eq.${messageId}`
);

const currentMessage = messages[0] || null;

if (!currentMessage) {
  throw new Error(
    `Message not found: ${messageId}`
  );
}

// ==================================================
// 6. GET CONVERSATION HISTORY
// ==================================================

const history = await supabaseGet(
  'messages',
  `select=id,sender_type,sender_id,content,created_at&conversation_id=eq.${conversationId}&order=created_at.asc&limit=20`
);

// ==================================================
// 7. GET CUSTOMER
// ==================================================

const customers = await supabaseGet(
  'customers',
  `select=id,full_name,email,phone&id=eq.${customerId}`
);

const customer = customers[0] || null;

// ==================================================
// 8. GET RELEVANT ORDER
// ==================================================

let order = null;

if (currentConversation.order_number) {

  const orders = await supabaseGet(
    'orders',
    `select=id,customer_id,order_number,status,total_amount,currency,ordered_at,expected_delivery_at,delivered_at,tracking_number&customer_id=eq.${customerId}&order_number=eq.${encodeURIComponent(currentConversation.order_number)}`
  );

  order = orders[0] || null;
}

// ==================================================
// 9. RETURN CONTEXT
// ==================================================

return [
  {
    json: {
      conversation: {
        id: currentConversation.id,
        customer_id: currentConversation.customer_id,
        channel: currentConversation.channel,
        status: currentConversation.status,
        queue: currentConversation.queue,
        language: currentConversation.language,
        intent: currentConversation.intent,
        sentiment: currentConversation.sentiment,

        // Keep score for application logic,
        // but the LLM will receive urgency_level later.
        urgency_score: urgencyScore,
        urgency_level: urgencyLevel,

        order_number: currentConversation.order_number,

        created_at: currentConversation.created_at,
        updated_at: currentConversation.updated_at
      },

      message: currentMessage,

      conversation_history: history,

      customer: customer,

      order: order
    }
  }
];

// W2 — SAVE FAQ SOURCES

const results = $input.all();

// Get message ID from W2 webhook
const messageId = $('Webhook').first().json.body.message_id;

if (!messageId) {
  throw new Error('Missing message_id.');
}

// Nothing to save
if (!results.length) {
  return [
    {
      json: {
        message_id: messageId,
        sources_saved: 0,
        sources: []
      }
    }
  ];
}

// Prepare sources
const sources = results.map((item, index) => ({
  message_id: messageId,
  chunk_id: item.json.chunk_id,
  similarity_score: item.json.similarity,
  rank: index + 1
}));

// Supabase connection
const supabaseUrl = 'https://jikdykibhyewrfnlpptv.supabase.co';
const supabaseKey = 'sb_secret_1g3-NRYivFEIBV415V3tnw_GcnjqMkI';

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: `${supabaseUrl}/rest/v1/ai_response_sources`,
  headers: {
    apikey: supabaseKey,
    Authorization: `Bearer ${supabaseKey}`,
    'Content-Type': 'application/json',
    Prefer: 'return=minimal'
  },
  body: sources
});

return [
  {
    json: {
      message_id: messageId,
      sources_saved: sources.length,
      sources: sources
    }
  }
];

// W2 — PREPARE GENERATION CONTEXT

const context = $('Get Context').first().json;
const faqResults = $('Search FAQ').all();

const sources = faqResults.map((item, index) => ({
  rank: index + 1,
  article_title: item.json.article_title,
  section_title: item.json.section_title,
  content: item.json.content,
  similarity: item.json.similarity
}));

return [
  {
    json: {
      message: context.message,
      conversation: context.conversation,
      conversation_history: context.conversation_history,
      customer: context.customer,
      order: context.order,
      faq_sources: sources
    }
  }
];

// W2 — SAVE AI GENERATED VERSION

const llmOutput = $('Generate AI Response').first().json;

if (!llmOutput.text) {
  throw new Error('Missing AI response.');
}

let data;

try {
  data = JSON.parse(llmOutput.text);
} catch (error) {
  throw new Error(
    `Invalid JSON from AI: ${error.message}`
  );
}

const webhook = $('Webhook').first().json;

const conversationId = webhook.body.conversation_id;
const messageId = webhook.body.message_id;

if (!conversationId) {
  throw new Error('Missing conversation_id.');
}

if (!messageId) {
  throw new Error('Missing message_id.');
}

if (!data.answer) {
  throw new Error('AI response does not contain an answer.');
}

// Supabase connection
const supabaseUrl = 'https://jikdykibhyewrfnlpptv.supabase.co';
const supabaseKey = 'sb_secret_1g3-NRYivFEIBV415V3tnw_GcnjqMkI';

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: `${supabaseUrl}/rest/v1/message_versions`,
  headers: {
    apikey: supabaseKey,
    Authorization: `Bearer ${supabaseKey}`,
    'Content-Type': 'application/json',
    Prefer: 'return=representation'
  },
  body: {
    conversation_id: conversationId,
    message_id: null,
    version_number: 1,
    content: data.answer,
    author_type: 'ai',
    author_id: null
  }
});

return [
  {
    json: {
      version_id: response[0]?.id,
      conversation_id: conversationId,
      message_id: messageId,
      version_number: 1,
      content: data.answer,
      author_type: 'ai',
      sources: data.sources || []
    }
  }
];

const sources = $json.sources ?? [];

const scores = sources
  .map(source => Number(source.similarity))
  .filter(score => Number.isFinite(score));

const rag_confidence = scores.length > 0
  ? Math.round(
      (scores.reduce((sum, score) => sum + score, 0) / scores.length) * 100
    )
  : 0;

return {
  json: {
    conversation_id: $json.conversation_id,
    rag_confidence
  }
};
